"""Package only real, reviewed native Blender renders and their authored source."""
from pathlib import Path
import json,base64,hashlib,zipfile,html,datetime
from PIL import Image
R=Path(__file__).resolve().parents[1];D=Path('/home/user/deliverables');D.mkdir(exist_ok=True);N=R/'renders/district/native'
reports=sorted([json.loads(p.read_text()) for p in N.glob('DISTVIEW_*.json')],key=lambda j:j['camera']);assert len(reports)==8
for j in reports:
 assert j['visual_inspection'].startswith('INSPECTED'),j['file']
 p=N/j['file'];assert hashlib.sha256(p.read_bytes()).hexdigest()==j['sha256'];assert Image.open(p).size==(2560,1440)
audit=json.loads((R/'evidence/DISTRICT_SOURCE_AUDIT.json').read_text());assert all(i['packed'] for i in audit['packed_images']);assert all(c['clear_at_probe_height'] for c in audit['architectural_route_head_height_spot_checks'])
assert hashlib.sha256((R/'source/NORDBAHNHOF_DISTRICT.blend').read_bytes()).hexdigest()==audit['source_sha256']
inv=json.loads((R/'docs/DISTRICT_INVENTORY.json').read_text());cnt=inv['component_counts'];hours=sum(j['cycles_render_seconds'] for j in reports)/3600
labels=['Station square','The covered exit','Market on Bahnhofplatz','The tram street','Into the neighborhood','Roofscape and urban blocks','Coffee, glass and bentwood','Through the doors, into the city']
captions=[
 'A connected square, civic clock entrance, newspaper kiosk and repeated photographic crowd.',
 'Opened door leaves, real steps and ramps, pane-by-pane iron/glass canopy and a furnished vestibule behind the facade.',
 'Awnings, crates and produce in front of layered masonry streets; repeated modern photographic scans are visible.',
 'A modeled electric streetcar,1435mm running gauge, flangeway grooves and overhead contact wire.',
 'Cross-avenue sidewalks, corner shops, cafés, delivery cart, bicycles and the station at the end of the street.',
 'The district comprises76 street buildings, not one facade backdrop. Some secondary backs/party walls remain simplified.',
 'Modeled cups/coffee/saucers, printed newspaper geometry, veined table and individually constructed bentwood chairs.',
 'The opened facade leads to the square. The saved full source has the same opening; it is not a render-only doorway trick.'
]
def data(p):return 'data:image/jpeg;base64,'+base64.b64encode(p.read_bytes()).decode()
cards=[]
for i,j in enumerate(reports):
 cards.append(f'''<figure id="view{i+1}"><div class="image"><img loading="lazy" src="{data(N/j['file'])}" alt="{html.escape(labels[i])}"><button type="button" class="enlarge" aria-label="Enlarge {html.escape(labels[i])}">Enlarge ↗</button></div><figcaption><span class="number">0{i+1}</span><div><h2>{labels[i]}</h2><p>{captions[i]}</p><small>2560 ×1440 native · {j['samples']}samples · Cycles / OIDN / AgX</small></div></figcaption></figure>''')
hero=cards[5];others=''.join(cards[i] for i in [0,1,7,2,3,4,6])
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>NORDBAHNHOF — The streets beyond</title><style>
:root{{--paper:#eae5da;--ink:#252d29;--muted:#656b62;--line:#b7baac;--accent:#72573b}}*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 Georgia,serif}}main{{max-width:1500px;padding:40px 5vw 80px;margin:auto}}header{{border-top:4px solid var(--ink);padding:24px 0 30px}}.eyebrow,small,nav,.facts,.number,button,footer{{font-family:Arial,sans-serif}}.eyebrow{{letter-spacing:.20em;font-size:11px;text-transform:uppercase}}h1{{font-weight:normal;line-height:1.02;font-size:clamp(46px,7.7vw,112px);letter-spacing:-.045em;margin:30px 0}}.intro{{display:grid;grid-template-columns:2fr 1fr;gap:9vw;align-items:end}}.intro p{{max-width:710px;font-size:19px;margin:0}}nav{{display:flex;gap:20px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:15px;font-size:12px}}a{{color:inherit;text-decoration:none;border-bottom:1px solid var(--muted)}}.facts{{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:22px 0;margin:28px 0 36px;gap:12px;font-size:11px;letter-spacing:.06em;text-transform:uppercase}}.facts strong{{display:block;font-family:Georgia,serif;font-size:40px;font-weight:normal;line-height:1.15;letter-spacing:-.03em}}figure{{margin:0 0 42px}}.image{{position:relative;background:#bbbcb3}}img{{width:100%;display:block;height:auto}}.enlarge{{position:absolute;right:12px;bottom:12px;border:1px solid #eee9da;background:#27312ae6;color:#fff;padding:8px 12px;font-size:11px;cursor:pointer}}figcaption{{padding:17px 0;border-bottom:1px solid var(--line);display:flex;gap:20px}}.number{{font-size:11px;color:var(--accent);padding-top:8px}}h2{{font-size:26px;font-weight:normal;letter-spacing:-.02em;margin:0 0 6px}}figcaption p{{margin:0 0 9px;color:#4c554d;max-width:850px}}small{{font-size:10px;letter-spacing:.035em;text-transform:uppercase;color:var(--muted)}}.collection{{display:grid;grid-template-columns:1fr 1fr;gap:0 28px}}.collection figure:nth-child(3),.collection figure:last-child{{grid-column:1/-1}}aside{{border-top:3px solid var(--ink);padding:24px 0;display:grid;grid-template-columns:1fr 2fr;gap:8vw}}aside h2{{font-size:35px}}aside p{{margin:0 0 15px}}footer{{border-top:1px solid var(--line);padding-top:20px;font-size:11px;color:var(--muted)}}dialog{{padding:0;border:0;background:#192019;color:white;max-width:96vw;max-height:96vh}}dialog::backdrop{{background:#111d}}dialog img{{width:auto;max-width:94vw;max-height:88vh;object-fit:contain}}dialog button{{display:block;margin:10px 10px 10px auto;padding:7px 15px;background:white;border:0;cursor:pointer}}@media(max-width:750px){{main{{padding:22px 20px 50px}}.intro,.collection,aside{{display:block}}nav{{margin-top:25px}}.facts{{grid-template-columns:1fr 1fr;gap:22px}}.facts strong{{font-size:34px}}figcaption{{gap:12px}}h2{{font-size:23px}}}}
</style></head><body><main><header><div class="eyebrow">NORDBAHNHOF / DISTRICT ATLAS / ARTISTIC WIP</div><h1>The streets<br>beyond the station.</h1><div class="intro"><p>An original historic-European neighborhood: masonry blocks, a busy forecourt, tram streets, markets and cafés—connected to the retained station by an actual covered exit.</p><nav><a href="#view6">Urban blocks</a><a href="#view2">The exit</a><a href="#view3">Street life</a><a href="#notes">Source &amp; limits</a></nav></div></header><div class="facts"><div><strong>76</strong>Street buildings</div><div><strong>{cnt['shop fascia']}</strong>3D shopfronts</div><div><strong>{cnt['photographic scanned people']}</strong>Placed scan instances</div><div><strong>8</strong>Native rendered views</div></div>{hero}<div class="collection">{others}</div><aside id="notes"><h2>Built, rendered,<br>and inspected.</h2><div><p>These are Blender scene renders, not generated-image replacements. Eight native 2560×1440 views,320 samples per view, overlapping HDR border tiles, external Intel OIDN 2.5.1 and Blender AgX. Actual logged Cycles render time, including tile setup and writing: <strong>{hours:.2f}hours</strong>. Image hashes and inspection notes accompany the project.</p><p>The full packed source retains all 76 buildings and the original 34 railway vehicles. Camera renders use documented memory-budget culling. Shops are shallow furnished 3D rooms and upper windows have shallow room reveals—not thousands of completed apartments.</p><p><strong>People:</strong>10 scanned identities in 12 poses, repeatedly instanced; modern clothing, not certified period costume. Architectural modules and repeated identities remain visible. This is an artistic static WIP, not a certified historic reconstruction, accessible/structural/railway validation, or completion of every item in the original station brief.</p><p><strong>Credits:</strong>HSRD-100 / DigitalRealityLab, CC BY 4.0 (normalized, decimated, resized and instanced); Poly Haven scanned surfaces, CC0. Full author/source/checksum records are included. Vitruvius was an atmospheric reference only; the district layout and architecture are original.</p><small>Exit source checks: centerline/lateral rays and floor-height spot checks—not certification.</small></div></aside><footer>NORDBAHNHOF · Bahnhofplatz district · Offline gallery · All images embedded; no external resources required.</footer></main><dialog id="lightbox"><button type="button" id="close">Close ×</button><img alt="Enlarged scene render"></dialog><script>const box=document.querySelector('#lightbox');document.querySelectorAll('.enlarge').forEach(b=>b.addEventListener('click',()=>{{const src=b.parentElement.querySelector('img');box.querySelector('img').src=src.src;box.querySelector('img').alt=src.alt;box.showModal()}}));document.querySelector('#close').onclick=()=>box.close();box.addEventListener('click',e=>{{if(e.target===box)box.close()}});</script></body></html>'''
gallery=D/'NORDBAHNHOF-district-gallery.html';gallery.write_text(page);(R/'NORDBAHNHOF-district-gallery.html').write_text(page)
preview=D/'NORDBAHNHOF-district-preview.jpg';Image.open(N/reports[5]['file']).save(preview,quality=94)
# All final native JPEGs/linear EXRs/reports, selected legacy source files, complete assets and generators.
files=[]
for folder in('assets','build','docs','evidence','design','validate','kits','exports','EVIDENCE'):
 root=R/folder
 if root.exists():files.extend(p for p in root.rglob('*') if p.is_file() and not any(x in p.parts for x in('__pycache__','.cache')) and p.suffix not in('.pyc',))
files.extend(p for p in (R/'source').glob('*.blend'))
files.extend(p for p in N.iterdir() if p.is_file() and not p.name.endswith('.denoised.pfm'))
files.extend(p for p in (R/'renders/realism/native').glob('*') if p.suffix in('.jpg','.json'))
files.extend(p for p in R.glob('*.md'))
files.append(R/'NORDBAHNHOF-district-gallery.html')
for name,paths in [('NORDBAHNHOF-district-complete.zip',files),('NORDBAHNHOF-district-renders.zip',[p for p in N.iterdir() if p.suffix in('.jpg','.json')]+[R/'NORDBAHNHOF-district-gallery.html',R/'DISTRICT_README.md'])]:
 with zipfile.ZipFile(D/name,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
  z.writestr('NORDBAHNHOF/README.md',(R/'DISTRICT_README.md').read_text())
  for p in sorted(set(paths)):z.write(p,Path('NORDBAHNHOF')/p.relative_to(R))
 with zipfile.ZipFile(D/name) as z:assert z.testzip() is None
meta={}
for p in [D/'NORDBAHNHOF-district-complete.zip',D/'NORDBAHNHOF-district-renders.zip',gallery,preview]:
 with p.open('rb') as f:h=hashlib.file_digest(f,'sha256').hexdigest()
 meta[p.name]={'bytes':p.stat().st_size,'sha256':h}
(D/'DISTRICT_PACKAGE.json').write_text(json.dumps(meta,indent=2));print(json.dumps(meta,indent=2))
